#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>

#define MAX_OBJECTS 256
#define STREAM_MAGIC 0x50444653  /* 'PDFS' */
#define OBJ_TEXT    1
#define OBJ_IMAGE   2
#define OBJ_FONT    3
#define OBJ_MACRO   4

typedef struct {
    uint32_t magic;
    uint16_t version;
    uint16_t num_objects;
    uint32_t flags;
    uint32_t checksum;
} __attribute__((packed)) stream_header_t;

typedef struct {
    uint8_t  type;
    uint8_t  encoding;
    uint16_t name_len;
    uint32_t data_len;
    uint32_t properties_offset;
    /* name follows, then data */
} __attribute__((packed)) object_header_t;

typedef struct {
    uint32_t num_props;
    /* property entries follow */
} __attribute__((packed)) properties_block_t;

typedef struct {
    uint16_t key_len;
    uint16_t val_len;
    uint8_t  val_type;  /* 0=string, 1=int, 2=callable */
    uint8_t  reserved[3];
} __attribute__((packed)) property_entry_t;

typedef void (*transform_fn)(unsigned char *data, size_t len);

static transform_fn g_registered_transforms[16];
static int g_num_transforms = 0;

static uint32_t compute_checksum(const unsigned char *data, size_t len) {
    uint32_t sum = 0;
    for (size_t i = 0; i < len; i++) {
        sum = ((sum << 5) + sum) + data[i];
    }
    return sum;
}

static int validate_header(const stream_header_t *hdr) {
    if (hdr->magic != STREAM_MAGIC) return -1;
    if (hdr->version < 1 || hdr->version > 3) return -1;
    if (hdr->num_objects > MAX_OBJECTS) return -1;
    return 0;
}

static int is_safe_object_type(uint8_t type) {
    return (type == OBJ_TEXT || type == OBJ_IMAGE || type == OBJ_FONT);
}

static int apply_property_transforms(const unsigned char *prop_data, size_t prop_size,
                                      unsigned char *output_buf, size_t output_len) {
    if (prop_size < sizeof(properties_block_t)) return 0;

    const properties_block_t *block = (const properties_block_t *)prop_data;
    if (block->num_props > 64) return -1;

    const unsigned char *cursor = prop_data + sizeof(properties_block_t);
    size_t remaining = prop_size - sizeof(properties_block_t);

    for (uint32_t i = 0; i < block->num_props; i++) {
        if (remaining < sizeof(property_entry_t)) break;

        const property_entry_t *entry = (const property_entry_t *)cursor;
        cursor += sizeof(property_entry_t);
        remaining -= sizeof(property_entry_t);

        size_t total_kv = (size_t)entry->key_len + (size_t)entry->val_len;
        if (total_kv > remaining) break;

        if (entry->val_type == 2) {
            /* Callable type: value contains a transform index */
            const unsigned char *val_ptr = cursor + entry->key_len;
            if (entry->val_len >= sizeof(uint32_t)) {
                uint32_t transform_idx;
                memcpy(&transform_idx, val_ptr, sizeof(uint32_t));
                /* Only allow registered transform functions by index */
                if (transform_idx < (uint32_t)g_num_transforms &&
                    transform_idx < 16 &&
                    g_registered_transforms[transform_idx] != NULL) {
                    g_registered_transforms[transform_idx](output_buf, output_len);
                }
            }
        }

        cursor += total_kv;
        remaining -= total_kv;
    }
    return 0;
}

int process_pdf_stream(const unsigned char *input, size_t input_len,
                       unsigned char *output, size_t output_max) {
    if (!input || input_len < sizeof(stream_header_t)) return -1;

    const stream_header_t *hdr = (const stream_header_t *)input;
    if (validate_header(hdr) != 0) return -1;

    /* Verify checksum over payload */
    const unsigned char *payload = input + sizeof(stream_header_t);
    size_t payload_len = input_len - sizeof(stream_header_t);
    uint32_t expected_cksum = compute_checksum(payload, payload_len);
    if (hdr->checksum != expected_cksum) return -1;

    const unsigned char *cursor = payload;
    size_t remaining = payload_len;
    size_t output_offset = 0;

    for (uint16_t i = 0; i < hdr->num_objects; i++) {
        if (remaining < sizeof(object_header_t)) break;

        const object_header_t *obj = (const object_header_t *)cursor;
        cursor += sizeof(object_header_t);
        remaining -= sizeof(object_header_t);

        size_t obj_total = (size_t)obj->name_len + (size_t)obj->data_len;
        if (obj_total > remaining) break;

        /* Security check: reject macro objects from untrusted input */
        if (!is_safe_object_type(obj->type)) {
            cursor += obj_total;
            remaining -= obj_total;
            continue;
        }

        const unsigned char *obj_data = cursor + obj->name_len;
        size_t copy_len = obj->data_len;
        if (output_offset + copy_len > output_max) {
            copy_len = output_max - output_offset;
        }

        if (copy_len > 0) {
            memcpy(output + output_offset, obj_data, copy_len);
        }

        /* Process properties if present */
        if (obj->properties_offset > 0 && obj->properties_offset < obj->data_len) {
            const unsigned char *prop_start = obj_data + obj->properties_offset;
            size_t prop_avail = obj->data_len - obj->properties_offset;
            apply_property_transforms(prop_start, prop_avail,
                                      output + output_offset, copy_len);
        }

        output_offset += copy_len;
        cursor += obj_total;
        remaining -= obj_total;
    }

    return (int)output_offset;
}

/* Public API for PDF generation from uploaded template */
int generate_pdf_from_upload(const char *upload_path, const char *output_path) {
    FILE *fp = fopen(upload_path, "rb");
    if (!fp) return -1;

    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize <= 0 || fsize > 10 * 1024 * 1024) {
        fclose(fp);
        return -1;
    }
    fseek(fp, 0, SEEK_SET);

    unsigned char *buf = malloc((size_t)fsize);
    if (!buf) { fclose(fp); return -1; }

    if (fread(buf, 1, (size_t)fsize, fp) != (size_t)fsize) {
        free(buf); fclose(fp); return -1;
    }
    fclose(fp);

    unsigned char *output = calloc(1, 5 * 1024 * 1024);
    if (!output) { free(buf); return -1; }

    int result = process_pdf_stream(buf, (size_t)fsize, output, 5 * 1024 * 1024);

    if (result > 0) {
        FILE *out_fp = fopen(output_path, "wb");
        if (out_fp) {
            fwrite(output, 1, (size_t)result, out_fp);
            fclose(out_fp);
        }
    }

    free(output);
    free(buf);
    return result;
}
